WITH filtered AS (SELECT *, TRIM(firmware) clean_firmware, status_bits * pressure status_bits_times_pressure FROM device_readings WHERE reading_ts > TIMESTAMP '2025-09-01 07:00:00'), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) + INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM filtered), sessions_device_readings AS (SELECT id, device_code, reading_ts, temp_c, pressure, status_bits, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged), gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) > INTERVAL '20' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM sessions_device_readings), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps), ranked AS (SELECT id, reading_ts, temp_c, status_bits, session_start_flag, session_id FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY status_bits ASC, id ASC) AS row_num FROM islands) x WHERE row_num = 1), cleaned AS (SELECT *, ROUND(session_id, 1) session_id_rounded, FLOOR(session_start_flag) session_start_flag_whole FROM ranked WHERE reading_ts > TIMESTAMP '2025-09-01 05:00:00') SELECT id, reading_ts, temp_c, session_start_flag, session_id, session_start_flag_whole FROM cleaned;
